// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _test(address _target, uint256 _value, uint256 _seed) internal {
        vm.assume(_target != address(c) && _target != address(this));
        vm.assume(_value > 0);
        uint beforeTarget = _target.balance;
        try c.sendMoney(_target, _value) {} catch { return; }
        uint afterTarget = _target.balance;
        assertTrue(afterTarget - beforeTarget == _value);
    }

    function testFuzz_test(address _target, uint256 _value, uint256 _seed) public {
        _test(_target, _value, _seed);
    }

    receive() external payable {}
}
